  if (!item || item.type === 'new') return { head: filterLabel, pos: String(games) }
  const pos = items.slice(0, index + 1).filter(i => i.type !== 'new').length
  return { head: item.group ? filterLabel + ' · ' + item.group : filterLabel, pos: pos + '/' + games }
